def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    # Continue the diagonal from the first cell, away from its matching neighbor.
                    ar, ac = r - dr, c - dc
                    while 0 <= ar < h and 0 <= ac < w:
                        if out[ar][ac] == bg:
                            out[ar][ac] = color
                        ar -= dr
                        ac -= dc
    return out
