    h, w = len(grid), len(grid[0])

    # A matching pair on a down-left diagonal marks a line extending up-right.
    for r in range(h - 1):
        for c in range(1, w):
            color = grid[r][c]
            if color != grid[r + 1][c - 1]:
                continue
            rr, cc = r, c
            while rr >= 0 and cc < w:
                out[rr][cc] = color
                rr -= 1
                cc += 1
    return out
