def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    for r in range(h - 1):
        for c in range(1, w):
            color = grid[r][c]
            if color == bg or color != grid[r + 1][c - 1]:
                continue
            rr, cc = r, c
            while rr >= 0 and cc < w:
                if out[rr][cc] == bg:
                    out[rr][cc] = color
                rr -= 1
                cc += 1
    return out
